/* Generated by tools/build-pwa.js. Keep updates waiting until the game is closed
   or the player explicitly applies them from the home screen. */
'use strict';
const VERSION=__VERSION__;
const FILES=__FILES__;
const SCOPE=new URL(self.registration.scope);
const PREFIX='fantallenatore:'+SCOPE.pathname+':';
const CACHE=PREFIX+VERSION;
const URLS=new Set(FILES.map(file=>new URL(file,SCOPE).href));
const INDEX=new URL('index.html',SCOPE).href;
self.addEventListener('install',event=>{
  event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES.map(file=>new Request(new URL(file,SCOPE),{cache:'reload'})))));
});
self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    const keys=await caches.keys();
    await Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE).map(key=>caches.delete(key)));
    await self.clients.claim();
  })());
});
self.addEventListener('message',event=>{
  if(event.data?.type==='ACTIVATE_UPDATE')event.waitUntil(self.skipWaiting());
});
self.addEventListener('fetch',event=>{
  const request=event.request;
  if(request.method!=='GET')return;
  const url=new URL(request.url);
  if(url.origin!==SCOPE.origin||!url.pathname.startsWith(SCOPE.pathname))return;
  url.search='';url.hash='';
  const homeNavigation=request.mode==='navigate'&&(url.href===SCOPE.href||url.href===INDEX);
  const key=homeNavigation?INDEX:url.href;
  if(!URLS.has(key))return;
  // One complete release per cache prevents mixing HTML and JS across updates.
  event.respondWith(caches.open(CACHE).then(async cache=>(await cache.match(key))||fetch(request)));
});
